import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Questionnaire.css"; // KEEP your CSS

function Questionnaire({ onNext }) {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    incomeStability: "",
    savingHabit: "",
    majorExpense: "",
    riskLevel: "",
    expenseControl: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleContinue = () => {
    // only call if exists → prevents crash
    if (typeof onNext === "function") {
      onNext(formData);
    }

    navigate("/spending-priority");
  };

  return (
    <div className="questionnaire-container">
      <h1 className="questionnaire-title">Financial Questionnaire</h1>

      <div className="questionnaire-form">

        <div className="question-block">
          <p>Income Stability</p>
          <select name="incomeStability" onChange={handleChange}>
            <option value="">Select</option>
            <option>Stable</option>
            <option>Somewhat Stable</option>
            <option>Unstable</option>
          </select>
        </div>

        <div className="question-block">
          <p>Saving Habit</p>
          <select name="savingHabit" onChange={handleChange}>
            <option value="">Select</option>
            <option>Regularly</option>
            <option>Sometimes</option>
            <option>Rarely</option>
          </select>
        </div>

        <div className="question-block">
          <p>Major Expense</p>
          <select name="majorExpense" onChange={handleChange}>
            <option value="">Select</option>
            <option>Food & Groceries</option>
            <option>Bills</option>
            <option>Shopping</option>
          </select>
        </div>

        <div className="question-block">
          <p>Risk Level</p>
          <select name="riskLevel" onChange={handleChange}>
            <option value="">Select</option>
            <option>Low</option>
            <option>Medium</option>
            <option>High</option>
          </select>
        </div>

        <div className="question-block">
          <p>Expense Control</p>
          <select name="expenseControl" onChange={handleChange}>
            <option value="">Select</option>
            <option>Good</option>
            <option>Average</option>
            <option>Poor</option>
          </select>
        </div>

        <button className="continue-btn" onClick={handleContinue}>
          Continue
        </button>

      </div>
    </div>
  );
}

export default Questionnaire;
